const confusion={"tense":["A finished-time marker usually requires past simple, not present perfect.","Do not use V2 after did/does; the auxiliary already carries tense.","Use present simple in future time clauses after when, until and as soon as.","Past perfect depends on event sequence, not simply on which clause comes first."],"pronoun":["Test pronoun case by removing a coordinated noun from the sentence.","Check whether a possessive form is followed by a noun.","Each/everyone is singular in formal agreement even when followed by plural nouns.","Classify countability before selecting much/many, less/fewer or a quantifier."],"preposition":["Separate fixed collocation from a general at/on/in rule.","Check whether the following word is a noun, gerund or full clause.","By means a deadline; until means continuation to an endpoint.","Similar verbs and nouns may take different fixed prepositions."],"sentence":["A long sentence can still have only one independent clause.","Two independent clauses cannot normally be joined by a comma alone.","Coordinated words must have parallel grammatical forms.","Place modifiers next to the words they describe; check the logical subject."],"translation":["Translate meaning and tense, not Bengali word order.","After did, use the base form; in future time clauses, avoid will after when.","Preserve tense on be in passive constructions and use the past participle.","Indirect questions use statement word order inside the embedded clause."],"idioms":["Interpret the whole expression figuratively rather than translating word by word.","Use context to distinguish phrasal verbs that share a main verb.","Check whether a phrasal verb is separable before placing a pronoun object.","Fixed formal expressions retain their standard preposition."],"vocabulary":["A near-synonym must fit the precise context and collocation.","Options may all be real words; use meaning and part of speech to distinguish them.","A correct root with the wrong suffix or word class is still incorrect.","Use contrast, cause, definition and tone as context clues."],"spelling":["Options can differ by one letter; compare exact letter positions.","Pronunciation does not reveal every silent letter or unstressed vowel.","A homophone can be correctly spelled but wrong for the sentence meaning.","British and American variants may both be valid; identify the convention first."]};
const examTrap={"tense":["The distractor often has a correct tense but the wrong time relation.","Watch auxiliary + main verb: one carries tense, the other stays base/V3/-ing.","IBA-style questions may hide the time clue in a subordinate clause.","BCS/bank items often test agreement and inversion alongside tense."],"pronoun":["A noun inside an of-phrase is a distractor; agree with the head word.","Formal case after prepositions and compound objects is a frequent test point.","Check antecedent clarity: the pronoun must point to one logical noun.","Countable vs uncountable noun often decides between otherwise similar options."],"preposition":["A semantically plausible preposition may break a fixed word partnership.","Despite/because of take noun forms; although/because take clauses.","Similar-looking time expressions are not interchangeable: by/until, since/for.","Look for verb + preposition and adjective + preposition patterns in options."],"sentence":["The closest noun is not always the subject; ignore interrupting phrases.","Connector meaning and punctuation must both fit the clause structure.","Parallelism traps often mix gerund, infinitive and noun forms.","A dangling modifier can make a grammatically polished option illogical."],"translation":["Literal translations often omit articles, auxiliaries or countability markers.","Check if an English sentence requires a subject even when Bengali omits it.","Word-for-word prepositions and idioms are common distractors.","Meaning may be right while tense or agreement is wrong; test both."],"idioms":["All options may look plausible if read literally; substitute a plain meaning.","Particle choice changes meaning: look into/after/up to have different senses.","A phrasal verb can be right in meaning but wrong in word order.","Register matters: formal expression choices may be tested by fixed usage."],"vocabulary":["Eliminate by word class first, then by exact meaning and tone.","A synonym can fit a dictionary definition but clash with the sentence collocation.","Negative prefixes are not freely interchangeable across word roots.","Watch commonly confused pairs and words with overlapping meanings."],"spelling":["A real word can be the wrong homophone for the context.","Do not trust sound alone for doubled consonants, silent letters or suffixes.","One option may use a valid US/UK variant; do not label it misspelled.","Proofreading questions may embed the error in plural or derived-word form."]};
