const prepositionChapterNotes=["<h1 id=\"preposition-ও-collocation\">Preposition ও Collocation</h1>\n<h2 id=\"competitive-job-examination-preparation-note\">Competitive Job Examination Preparation Note</h2>\n<p><strong>উপযোগী পরীক্ষা:</strong> BCS, বাংলাদেশ ব্যাংক, ব্যাংক নিয়োগ, CAAB, IBA, NTRCA ও অন্যান্য প্রতিযোগিতামূলক পরীক্ষা।</p>\n<p>Preposition-এর প্রশ্নে শুধু <em>in, on, at</em> মুখস্থ করলেই হয় না। বাক্যে সময়, স্থান, দিক, সম্পর্ক এবং শব্দের সঙ্গে কোন preposition স্বাভাবিকভাবে বসে—সেটি বুঝতে হয়। বিশেষ করে <strong>verb + preposition, adjective + preposition, noun + preposition</strong> এবং fixed collocation পরীক্ষায় বেশি আসে।</p>\n<hr />\n<h2 id=\"১-preposition-ধারণা-ও-কাজ\">১. Preposition: ধারণা ও কাজ</h2>\n<p><strong>Preposition</strong> সাধারণত noun, pronoun বা gerund-এর আগে বসে বাক্যের অন্য শব্দের সঙ্গে তার সম্পর্ক বোঝায়।</p>\n<ul>\n<li><em>The file is <strong>on</strong> the desk.</em> — স্থান/অবস্থান</li>\n<li><em>She arrived <strong>at</strong> noon.</em> — সময়</li>\n<li><em>They travelled <strong>by</strong> bus.</em> — মাধ্যম</li>\n<li><em>He is interested <strong>in</strong> research.</em> — শব্দের সঙ্গে স্থির সম্পর্ক</li>\n</ul>\n<p>Preposition-এর পরে সাধারণত <strong>noun, pronoun বা gerund</strong> বসে:</p>\n<ul>\n<li><em>in the room</em> — noun</li>\n<li><em>between you and <strong>me</strong></em> — pronoun-এর object form</li>\n<li><em>interested in <strong>learning</strong></em> — gerund</li>\n</ul>\n<h3 id=\"phrase-এর-ধরন\">Phrase-এর ধরন</h3>\n<ul>\n<li><strong>Prepositional phrase:</strong> <em>under the table, after lunch, in the morning</em></li>\n<li><strong>Verb + preposition:</strong> <em>depend on, listen to, belong to</em></li>\n<li><strong>Adjective + preposition:</strong> <em>good at, afraid of, responsible for</em></li>\n<li><strong>Noun + preposition:</strong> <em>reason for, solution to, access to</em></li>\n</ul>\n<p>একই preposition সব জায়গায় একই অর্থ দেয় না। যেমন:</p>\n<ul>\n<li><em>She is <strong>at</strong> the office.</em> — স্থানে</li>\n<li><em>She laughed <strong>at</strong> the joke.</em> — কোনো কিছুর প্রতিক্রিয়ায়</li>\n<li><em>The price is <strong>at</strong> Tk 500.</em> — নির্দিষ্ট পর্যায়ে/দামে</li>\n</ul>\n<hr />\n<h2 id=\"২-preposition-of-time-at-on-in\">২. Preposition of Time: At, On, In</h2>\n<h3 id=\"at-নির্দিষ্ট-সময়-বা-মুহূর্ত\">At: নির্দিষ্ট সময় বা মুহূর্ত</h3>\n<ul>\n<li><strong>at 6 o’clock</strong></li>\n<li><strong>at noon</strong></li>\n<li><strong>at midnight</strong></li>\n<li><strong>at sunrise</strong></li>\n<li><strong>at night</strong></li>\n<li><strong>at the moment</strong></li>\n</ul>\n<blockquote>\n<p><em>The test begins <strong>at 10:00 a.m.</strong></em></p>\n</blockquote>\n<h3 id=\"on-নির্দিষ্ট-দিন-বা-তারিখ\">On: নির্দিষ্ট দিন বা তারিখ</h3>\n<ul>\n<li><strong>on Monday</strong></li>\n<li><strong>on 20 November</strong></li>\n<li><strong>on my birthday</strong></li>\n<li><strong>on Monday morning</strong></li>\n<li><strong>on the first day</strong></li>\n</ul>\n<blockquote>\n<p><em>The interview is <strong>on Thursday</strong>.</em><br />\n<em>The application closes <strong>on 20 November</strong>.</em></p>\n</blockquote>\n<p>দিনের অংশের সঙ্গে নির্দিষ্ট দিন থাকলে সাধারণত <strong>on</strong>:</p>\n<ul>\n<li><strong>on Friday evening</strong></li>\n<li><strong>on Monday morning</strong></li>\n</ul>\n<h3 id=\"in-দীর্ঘ-সময়-বা-সময়ের-পরিসর\">In: দীর্ঘ সময় বা সময়ের পরিসর</h3>\n<ul>\n<li><strong>in June</strong></li>\n<li><strong>in 2026</strong></li>\n<li><strong>in winter</strong></li>\n<li><strong>in the morning</strong></li>\n<li><strong>in the afternoon</strong></li>\n<li><strong>in the evening</strong></li>\n<li><strong>in the 1990s</strong></li>\n</ul>\n<blockquote>\n<p><em>She graduated <strong>in 2022</strong>.</em></p>\n</blockquote>\n<h3 id=\"at-on-inদ্রুত-তুলনা\">At, On, In—দ্রুত তুলনা</h3>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>Preposition</th>\n<th>সাধারণ ব্যবহার</th>\n<th>উদাহরণ</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>at</strong></td>\n<td>নির্দিষ্ট সময়</td>\n<td>at 7 p.m., at noon</td>\n</tr>\n<tr class=\"even\">\n<td><strong>on</strong></td>\n<td>দিন/তারিখ</td>\n<td>on Sunday, on 10 May</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>in</strong></td>\n<td>মাস/বছর/ঋতু/দীর্ঘ সময়</td>\n<td>in July, in 2025, in winter</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"সময়ের-আগে-preposition-না-ও-বসে\">সময়ের আগে preposition না-ও বসে</h3>\n<p><strong>last, next, every, this, that</strong> দিয়ে সময় বোঝালে সাধারণত আগে preposition লাগে না।</p>\n<ul>\n<li>✅ <em>I met him <strong>last week</strong>.</em></li>\n<li>❌ <em>I met him <strong>in last week</strong>.</em></li>\n<li>✅ <em>We will meet <strong>next Monday</strong>.</em></li>\n<li>❌ <em>We will meet <strong>on next Monday</strong>.</em></li>\n<li>✅ <em>She works <strong>every day</strong>.</em></li>\n<li>✅ <em>I will call you <strong>this evening</strong>.</em></li>\n</ul>\n<hr />\n","<h2 id=\"৩-since-for-during-by-until\">৩. Since, For, During, By, Until</h2>\n<h3 id=\"since-বনাম-for\">Since বনাম For</h3>\n<ul>\n<li><strong>since + নির্দিষ্ট starting point</strong>\n<ul>\n<li>since 2020</li>\n<li>since Monday</li>\n<li>since morning</li>\n</ul></li>\n<li><strong>for + সময়ের দৈর্ঘ্য</strong>\n<ul>\n<li>for two years</li>\n<li>for three hours</li>\n<li>for a long time</li>\n</ul></li>\n</ul>\n<blockquote>\n<p><em>He has worked here <strong>since 2021</strong>.</em><br />\n<em>He has worked here <strong>for five years</strong>.</em></p>\n</blockquote>\n<ul>\n<li>❌ <em>since five years</em></li>\n<li>✅ <em>for five years</em></li>\n</ul>\n<h3 id=\"during-বনাম-while\">During বনাম While</h3>\n<ul>\n<li><strong>during + noun বা noun phrase</strong>\n<ul>\n<li><em>during the meeting</em></li>\n<li><em>during the holidays</em></li>\n</ul></li>\n<li><strong>while + clause</strong>\n<ul>\n<li><em>while the meeting was taking place</em></li>\n<li><em>while I was studying</em></li>\n</ul></li>\n</ul>\n<blockquote>\n<p><em>The lights went out <strong>during the meeting</strong>.</em><br />\n<em>The lights went out <strong>while we were meeting</strong>.</em></p>\n</blockquote>\n<h3 id=\"by-বনাম-untiltill\">By বনাম Until/Till</h3>\n<ul>\n<li><strong>by</strong> = কোনো deadline-এর মধ্যে বা তার আগে\n<ul>\n<li><em>Submit the form <strong>by Friday</strong>.</em> — শুক্রবারের মধ্যে জমা দিন।</li>\n</ul></li>\n<li><strong>until/till</strong> = কোনো সময় পর্যন্ত কাজ চলতে থাকবে\n<ul>\n<li><em>The office will remain open <strong>until 5 p.m.</strong></em></li>\n</ul></li>\n</ul>\n<blockquote>\n<p><em>I will finish the report <strong>by noon</strong>.</em><br />\n<em>I will work <strong>until noon</strong>.</em></p>\n</blockquote>\n<h3 id=\"fromto-betweenand\">From…to, Between…and</h3>\n<ul>\n<li><p><strong>from Monday to Friday</strong></p></li>\n<li><p><strong>between 9 a.m. and 5 p.m.</strong></p></li>\n<li><p>✅ <em>The course runs <strong>from June to August</strong>.</em></p></li>\n<li><p>✅ <em>The office is open <strong>between 9 and 5</strong>.</em></p></li>\n<li><p>❌ <em>between 9 to 5</em></p></li>\n</ul>\n<hr />\n","<h2 id=\"৪-preposition-of-place-at-in-on\">৪. Preposition of Place: At, In, On</h2>\n<h3 id=\"at-নির্দিষ্ট-point-বা-স্থান\">At: নির্দিষ্ট point বা স্থান</h3>\n<ul>\n<li><strong>at the bus stop</strong></li>\n<li><strong>at the door</strong></li>\n<li><strong>at the entrance</strong></li>\n<li><strong>at the station</strong></li>\n<li><strong>at work</strong></li>\n<li><strong>at school</strong></li>\n</ul>\n<blockquote>\n<p><em>Someone is waiting <strong>at the gate</strong>.</em></p>\n</blockquote>\n<h3 id=\"in-কোনো-ঘেরা-স্থান-এলাকা-বা-বড়-অঞ্চল\">In: কোনো ঘেরা স্থান, এলাকা বা বড় অঞ্চল</h3>\n<ul>\n<li><strong>in a room</strong></li>\n<li><strong>in a building</strong></li>\n<li><strong>in Dhaka</strong></li>\n<li><strong>in Bangladesh</strong></li>\n<li><strong>in a box</strong></li>\n<li><strong>in the garden</strong></li>\n</ul>\n<blockquote>\n<p><em>The documents are <strong>in the drawer</strong>.</em></p>\n</blockquote>\n<h3 id=\"on-কোনো-পৃষ্ঠের-ওপর-বা-কোনো-রেখাপথে\">On: কোনো পৃষ্ঠের ওপর বা কোনো রেখা/পথে</h3>\n<ul>\n<li><strong>on the table</strong></li>\n<li><strong>on the wall</strong></li>\n<li><strong>on the floor</strong></li>\n<li><strong>on the screen</strong></li>\n<li><strong>on the road</strong></li>\n</ul>\n<blockquote>\n<p><em>The notice is <strong>on the board</strong>.</em></p>\n</blockquote>\n<h3 id=\"ঠিকানা-ও-প্রতিষ্ঠান-সংক্রান্ত-ব্যবহার\">ঠিকানা ও প্রতিষ্ঠান-সংক্রান্ত ব্যবহার</h3>\n<ul>\n<li><strong>at</strong> a specific address or point: <em>at 25 College Road</em></li>\n<li><strong>in</strong> a city/country: <em>in Cumilla, in Bangladesh</em></li>\n<li><strong>at</strong> an institution/activity: <em>at university, at work</em></li>\n<li><strong>in</strong> a room/building: <em>in the classroom, in the office</em></li>\n</ul>\n<p><strong>Street/road</strong>-এর ব্যবহারে British ও American English-এ কিছু পার্থক্য দেখা যায়। পরীক্ষার বাক্যে দেওয়া context ও প্রচলিত usage অনুসরণ করুন।</p>\n<hr />\n","<h2 id=\"৫-অবস্থান-ও-দিকের-preposition\">৫. অবস্থান ও দিকের Preposition</h2>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>Preposition</th>\n<th>অর্থ</th>\n<th>উদাহরণ</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>above</strong></td>\n<td>উপরে, সরাসরি স্পর্শ না-ও করতে পারে</td>\n<td>The fan is above the table.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>over</strong></td>\n<td>উপরে/ঢেকে/এক পাশ থেকে অন্য পাশে</td>\n<td>A bridge over the river.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>below</strong></td>\n<td>নিচে, সরাসরি নিচে না-ও হতে পারে</td>\n<td>The temperature fell below zero.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>under</strong></td>\n<td>নিচে বা আচ্ছাদিত অবস্থায়</td>\n<td>The bag is under the chair.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>beside</strong></td>\n<td>পাশে</td>\n<td>Sit beside me.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>besides</strong></td>\n<td>ছাড়াও/অতিরিক্তভাবে</td>\n<td>Besides English, she studies French.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>between</strong></td>\n<td>পৃথক ব্যক্তি/বস্তুর মধ্যে</td>\n<td>between the two offices</td>\n</tr>\n<tr class=\"even\">\n<td><strong>among</strong></td>\n<td>কোনো দল বা গোষ্ঠীর মধ্যে</td>\n<td>among the candidates</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>behind</strong></td>\n<td>পেছনে</td>\n<td>behind the building</td>\n</tr>\n<tr class=\"even\">\n<td><strong>in front of</strong></td>\n<td>সামনে</td>\n<td>in front of the entrance</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>opposite</strong></td>\n<td>বিপরীতে</td>\n<td>opposite the bank</td>\n</tr>\n<tr class=\"even\">\n<td><strong>near</strong></td>\n<td>কাছে</td>\n<td>near the station</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"between-বনাম-among\">Between বনাম Among</h3>\n<ul>\n<li><strong>between</strong> সাধারণত দুইটি বা পৃথকভাবে শনাক্ত করা ব্যক্তি/বস্তুর মধ্যে:\n<ul>\n<li><em>The agreement was signed <strong>between the two agencies</strong>.</em></li>\n<li>একাধিক হলেও যখন প্রত্যেক পক্ষ আলাদাভাবে চিহ্নিত, তখনও <strong>between</strong> ব্যবহার হতে পারে।</li>\n</ul></li>\n<li><strong>among</strong> কোনো দল বা গোষ্ঠীর সদস্যদের মধ্যে:\n<ul>\n<li><em>The award was shared <strong>among the five winners</strong>.</em></li>\n</ul></li>\n</ul>\n<h3 id=\"beside-বনাম-besides\">Beside বনাম Besides</h3>\n<ul>\n<li><strong>beside</strong> = পাশে\n<ul>\n<li><em>He sat beside his colleague.</em></li>\n</ul></li>\n<li><strong>besides</strong> = ছাড়াও\n<ul>\n<li><em>Besides statistics, she studied computer science.</em></li>\n</ul></li>\n</ul>\n<hr />\n<h2 id=\"৬-movement-ও-direction-to-into-onto-across\">৬. Movement ও Direction: To, Into, Onto, Across</h2>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>Preposition</th>\n<th>অর্থ</th>\n<th>উদাহরণ</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>to</strong></td>\n<td>কোনো গন্তব্যের দিকে/পর্যন্ত</td>\n<td>go to the office</td>\n</tr>\n<tr class=\"even\">\n<td><strong>into</strong></td>\n<td>বাইরে থেকে ভেতরে প্রবেশ</td>\n<td>walk into the room</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>onto</strong></td>\n<td>কোনো পৃষ্ঠের ওপর ওঠা/যাওয়া</td>\n<td>climb onto the roof</td>\n</tr>\n<tr class=\"even\">\n<td><strong>towards</strong></td>\n<td>কোনো দিকের দিকে; গন্তব্যে পৌঁছানো নিশ্চিত নয়</td>\n<td>walk towards the gate</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>across</strong></td>\n<td>এক পাশ থেকে অন্য পাশে</td>\n<td>swim across the river</td>\n</tr>\n<tr class=\"even\">\n<td><strong>through</strong></td>\n<td>ভেতর দিয়ে/মধ্য দিয়ে</td>\n<td>walk through the tunnel</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>along</strong></td>\n<td>কোনো পথ বা রেখা ধরে</td>\n<td>walk along the road</td>\n</tr>\n<tr class=\"even\">\n<td><strong>past</strong></td>\n<td>কোনো স্থান অতিক্রম করে সামনে</td>\n<td>drive past the school</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>over</strong></td>\n<td>উপর দিয়ে/এক পাশ থেকে অন্য পাশে</td>\n<td>fly over the hills</td>\n</tr>\n<tr class=\"even\">\n<td><strong>under</strong></td>\n<td>নিচ দিয়ে</td>\n<td>pass under the bridge</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"into-বনাম-in\">Into বনাম In</h3>\n<ul>\n<li><strong>into</strong> চলাচল বা প্রবেশ বোঝায়:\n<ul>\n<li><em>She walked <strong>into</strong> the room.</em></li>\n</ul></li>\n<li><strong>in</strong> অবস্থান বোঝায়:\n<ul>\n<li><em>She is <strong>in</strong> the room.</em></li>\n</ul></li>\n</ul>\n<p>একইভাবে:</p>\n<ul>\n<li><em>The cat jumped <strong>onto</strong> the table.</em> — টেবিলের ওপর উঠল।</li>\n<li><em>The cat is <strong>on</strong> the table.</em> — টেবিলের ওপর আছে।</li>\n</ul>\n<h3 id=\"to-at-in-এর-সঙ্গে-সাধারণ-verb\">To, At, In-এর সঙ্গে সাধারণ verb</h3>\n<ul>\n<li><strong>go to</strong> a place</li>\n<li><strong>arrive at</strong> a small place/point: <em>arrive at the station</em></li>\n<li><strong>arrive in</strong> a city/country: <em>arrive in Dhaka</em></li>\n<li><strong>reach</strong> a place—এর পরে সাধারণত <strong>to/at</strong> লাগে না:\n<ul>\n<li>✅ <em>We reached the station.</em></li>\n<li>❌ <em>We reached to the station.</em></li>\n</ul></li>\n</ul>\n<hr />\n","<h2 id=\"৭-verb--preposition-collocation\">৭. Verb + Preposition Collocation</h2>\n<p>অনেক verb নির্দিষ্ট preposition-এর সঙ্গে ব্যবহৃত হয়। এগুলোকে verb–preposition collocation বলা হয়। সাধারণত আলাদা করে মুখস্থ করতে হয়।</p>\n<h3 id=\"গুরুত্বপূর্ণ-verb--preposition\">গুরুত্বপূর্ণ Verb + Preposition</h3>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>Verb phrase</th>\n<th>অর্থ/উদাহরণ</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>abide <strong>by</strong></td>\n<td>নিয়ম মেনে চলা — abide by the rules</td>\n</tr>\n<tr class=\"even\">\n<td>abstain <strong>from</strong></td>\n<td>বিরত থাকা — abstain from smoking</td>\n</tr>\n<tr class=\"odd\">\n<td>accuse someone <strong>of</strong></td>\n<td>অভিযোগ করা — accuse him of theft</td>\n</tr>\n<tr class=\"even\">\n<td>adapt <strong>to</strong></td>\n<td>মানিয়ে নেওয়া — adapt to change</td>\n</tr>\n<tr class=\"odd\">\n<td>agree <strong>with</strong> someone/an opinion</td>\n<td>কারও সঙ্গে/মতের সঙ্গে একমত</td>\n</tr>\n<tr class=\"even\">\n<td>agree <strong>to</strong> a proposal/plan</td>\n<td>প্রস্তাব বা পরিকল্পনায় সম্মতি</td>\n</tr>\n<tr class=\"odd\">\n<td>agree <strong>on</strong> a subject/date</td>\n<td>কোনো বিষয়ে বা তারিখে একমত হওয়া</td>\n</tr>\n<tr class=\"even\">\n<td>apply <strong>for</strong> a job</td>\n<td>চাকরির জন্য আবেদন করা</td>\n</tr>\n<tr class=\"odd\">\n<td>apply <strong>to</strong> a university/organization</td>\n<td>কোনো প্রতিষ্ঠান/বিশ্ববিদ্যালয়ে আবেদন করা</td>\n</tr>\n<tr class=\"even\">\n<td>approve <strong>of</strong></td>\n<td>সমর্থন/অনুমোদন করা</td>\n</tr>\n<tr class=\"odd\">\n<td>believe <strong>in</strong></td>\n<td>বিশ্বাস করা — believe in hard work</td>\n</tr>\n<tr class=\"even\">\n<td>belong <strong>to</strong></td>\n<td>মালিকানাধীন হওয়া — belong to the department</td>\n</tr>\n<tr class=\"odd\">\n<td>benefit <strong>from</strong></td>\n<td>উপকৃত হওয়া</td>\n</tr>\n<tr class=\"even\">\n<td>care <strong>about</strong></td>\n<td>গুরুত্ব দেওয়া/উদ্বিগ্ন হওয়া</td>\n</tr>\n<tr class=\"odd\">\n<td>care <strong>for</strong></td>\n<td>দেখাশোনা করা বা পছন্দ করা—context অনুযায়ী</td>\n</tr>\n<tr class=\"even\">\n<td>consist <strong>of</strong></td>\n<td>দিয়ে গঠিত হওয়া</td>\n</tr>\n<tr class=\"odd\">\n<td>contribute <strong>to</strong></td>\n<td>অবদান রাখা</td>\n</tr>\n<tr class=\"even\">\n<td>depend <strong>on/upon</strong></td>\n<td>নির্ভর করা</td>\n</tr>\n<tr class=\"odd\">\n<td>differ <strong>from</strong></td>\n<td>থেকে ভিন্ন হওয়া</td>\n</tr>\n<tr class=\"even\">\n<td>insist <strong>on</strong></td>\n<td>জোর দেওয়া</td>\n</tr>\n<tr class=\"odd\">\n<td>listen <strong>to</strong></td>\n<td>শোনা</td>\n</tr>\n<tr class=\"even\">\n<td>object <strong>to</strong></td>\n<td>আপত্তি করা</td>\n</tr>\n<tr class=\"odd\">\n<td>participate <strong>in</strong></td>\n<td>অংশগ্রহণ করা</td>\n</tr>\n<tr class=\"even\">\n<td>prevent someone <strong>from</strong></td>\n<td>বাধা দেওয়া</td>\n</tr>\n<tr class=\"odd\">\n<td>provide someone <strong>with</strong></td>\n<td>কাউকে কিছু সরবরাহ করা</td>\n</tr>\n<tr class=\"even\">\n<td>recover <strong>from</strong></td>\n<td>সেরে ওঠা</td>\n</tr>\n<tr class=\"odd\">\n<td>refer <strong>to</strong></td>\n<td>উল্লেখ/নির্দেশ করা</td>\n</tr>\n<tr class=\"even\">\n<td>rely <strong>on/upon</strong></td>\n<td>নির্ভর করা</td>\n</tr>\n<tr class=\"odd\">\n<td>suffer <strong>from</strong></td>\n<td>ভোগা</td>\n</tr>\n<tr class=\"even\">\n<td>succeed <strong>in</strong></td>\n<td>সফল হওয়া</td>\n</tr>\n<tr class=\"odd\">\n<td>wait <strong>for</strong></td>\n<td>অপেক্ষা করা</td>\n</tr>\n</tbody>\n</table></div>\n<p>উদাহরণ:</p>\n<ul>\n<li><em>The committee <strong>consists of</strong> five members.</em></li>\n<li><em>The candidate <strong>applied for</strong> the post.</em></li>\n<li><em>The new employee quickly <strong>adapted to</strong> the work.</em></li>\n<li><em>Regular practice helps students <strong>succeed in</strong> the examination.</em></li>\n</ul>\n<h3 id=\"যে-verb-গুলোর-পরে-সাধারণত-preposition-বসে-না\">যে verb-গুলোর পরে সাধারণত preposition বসে না</h3>\n<p>কিছু verb-এর পরে object সরাসরি বসে। এগুলোর পরে অযথা preposition বসানো চাকরির পরীক্ষার সাধারণ ফাঁদ।</p>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>ভুল</th>\n<th>সঠিক</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>discuss <strong>about</strong> the issue</td>\n<td>discuss the issue</td>\n</tr>\n<tr class=\"even\">\n<td>enter <strong>into</strong> the room</td>\n<td>enter the room</td>\n</tr>\n<tr class=\"odd\">\n<td>reach <strong>to</strong> the station</td>\n<td>reach the station</td>\n</tr>\n<tr class=\"even\">\n<td>approach <strong>to</strong> the manager</td>\n<td>approach the manager</td>\n</tr>\n<tr class=\"odd\">\n<td>resemble <strong>with</strong> his father</td>\n<td>resemble his father</td>\n</tr>\n<tr class=\"even\">\n<td>mention <strong>about</strong> the matter</td>\n<td>mention the matter</td>\n</tr>\n<tr class=\"odd\">\n<td>order <strong>for</strong> a meal</td>\n<td>order a meal</td>\n</tr>\n<tr class=\"even\">\n<td>request <strong>for</strong> assistance (verb হিসেবে)</td>\n<td>request assistance</td>\n</tr>\n<tr class=\"odd\">\n<td>marry <strong>with</strong> someone</td>\n<td>marry someone / be married to someone</td>\n</tr>\n</tbody>\n</table></div>\n<p>কিছু phrase-এ একই শব্দ noun হলে preposition লাগতে পারে:</p>\n<ul>\n<li><em>They <strong>discussed the issue</strong>.</em> — verb; preposition নেই।</li>\n<li><em>They had a <strong>discussion about the issue</strong>.</em> — noun; about ব্যবহৃত হয়েছে।</li>\n</ul>\n<hr />\n","<h2 id=\"৮-adjective--preposition-collocation\">৮. Adjective + Preposition Collocation</h2>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>Adjective phrase</th>\n<th>উদাহরণ</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>afraid <strong>of</strong></td>\n<td>afraid of snakes</td>\n</tr>\n<tr class=\"even\">\n<td>aware <strong>of</strong></td>\n<td>aware of the risks</td>\n</tr>\n<tr class=\"odd\">\n<td>capable <strong>of</strong></td>\n<td>capable of solving the problem</td>\n</tr>\n<tr class=\"even\">\n<td>fond <strong>of</strong></td>\n<td>fond of music</td>\n</tr>\n<tr class=\"odd\">\n<td>full <strong>of</strong></td>\n<td>full of information</td>\n</tr>\n<tr class=\"even\">\n<td>guilty <strong>of</strong></td>\n<td>guilty of the offence</td>\n</tr>\n<tr class=\"odd\">\n<td>interested <strong>in</strong></td>\n<td>interested in research</td>\n</tr>\n<tr class=\"even\">\n<td>involved <strong>in</strong></td>\n<td>involved in the project</td>\n</tr>\n<tr class=\"odd\">\n<td>successful <strong>in</strong></td>\n<td>successful in business</td>\n</tr>\n<tr class=\"even\">\n<td>good <strong>at</strong></td>\n<td>good at mathematics</td>\n</tr>\n<tr class=\"odd\">\n<td>bad <strong>at</strong></td>\n<td>bad at spelling</td>\n</tr>\n<tr class=\"even\">\n<td>responsible <strong>for</strong></td>\n<td>responsible for the report</td>\n</tr>\n<tr class=\"odd\">\n<td>famous <strong>for</strong></td>\n<td>famous for its history</td>\n</tr>\n<tr class=\"even\">\n<td>ready <strong>for</strong></td>\n<td>ready for the interview</td>\n</tr>\n<tr class=\"odd\">\n<td>suitable <strong>for</strong></td>\n<td>suitable for the post</td>\n</tr>\n<tr class=\"even\">\n<td>different <strong>from</strong></td>\n<td>different from the original</td>\n</tr>\n<tr class=\"odd\">\n<td>similar <strong>to</strong></td>\n<td>similar to the previous model</td>\n</tr>\n<tr class=\"even\">\n<td>married <strong>to</strong></td>\n<td>married to a doctor</td>\n</tr>\n<tr class=\"odd\">\n<td>dependent <strong>on</strong></td>\n<td>dependent on public transport</td>\n</tr>\n<tr class=\"even\">\n<td>keen <strong>on</strong></td>\n<td>keen on learning</td>\n</tr>\n<tr class=\"odd\">\n<td>familiar <strong>with</strong></td>\n<td>familiar with the software</td>\n</tr>\n<tr class=\"even\">\n<td>pleased <strong>with</strong></td>\n<td>pleased with the result</td>\n</tr>\n<tr class=\"odd\">\n<td>proud <strong>of</strong></td>\n<td>proud of her achievement</td>\n</tr>\n<tr class=\"even\">\n<td>worried <strong>about</strong></td>\n<td>worried about the deadline</td>\n</tr>\n<tr class=\"odd\">\n<td>angry <strong>with</strong> a person</td>\n<td>angry with the employee</td>\n</tr>\n<tr class=\"even\">\n<td>angry <strong>about</strong> a situation</td>\n<td>angry about the decision</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"পরীক্ষায়-বেশি-আসা-adjective-patterns\">পরীক্ষায় বেশি আসা adjective patterns</h3>\n<ul>\n<li><strong>superior to</strong>, <strong>inferior to</strong>, <strong>senior to</strong>, <strong>junior to</strong>\n<ul>\n<li>✅ <em>This model is superior <strong>to</strong> the previous one.</em></li>\n<li>❌ <em>superior than</em></li>\n</ul></li>\n<li><strong>prefer X to Y</strong>\n<ul>\n<li>✅ <em>I prefer tea <strong>to</strong> coffee.</em></li>\n<li>❌ <em>prefer tea than coffee</em></li>\n</ul></li>\n<li><strong>different from</strong> সবচেয়ে প্রচলিত; কিছু variety-তে <strong>different to/than</strong>-ও দেখা যায়। পরীক্ষায় সাধারণত <strong>different from</strong> নিরাপদ উত্তর।</li>\n</ul>\n<hr />\n","<h2 id=\"৯-noun--preposition-collocation\">৯. Noun + Preposition Collocation</h2>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>Noun phrase</th>\n<th>উদাহরণ</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>access <strong>to</strong></td>\n<td>access to information</td>\n</tr>\n<tr class=\"even\">\n<td>answer <strong>to</strong></td>\n<td>the answer to the question</td>\n</tr>\n<tr class=\"odd\">\n<td>attitude <strong>towards/to</strong></td>\n<td>attitude towards work</td>\n</tr>\n<tr class=\"even\">\n<td>cause <strong>of</strong></td>\n<td>the cause of the problem</td>\n</tr>\n<tr class=\"odd\">\n<td>demand <strong>for</strong></td>\n<td>demand for skilled workers</td>\n</tr>\n<tr class=\"even\">\n<td>effect <strong>on</strong></td>\n<td>the effect on the environment</td>\n</tr>\n<tr class=\"odd\">\n<td>increase/decrease <strong>in</strong></td>\n<td>an increase in prices</td>\n</tr>\n<tr class=\"even\">\n<td>interest <strong>in</strong></td>\n<td>interest in science</td>\n</tr>\n<tr class=\"odd\">\n<td>invitation <strong>to</strong></td>\n<td>an invitation to the event</td>\n</tr>\n<tr class=\"even\">\n<td>need <strong>for</strong></td>\n<td>the need for reform</td>\n</tr>\n<tr class=\"odd\">\n<td>reason <strong>for</strong></td>\n<td>a reason for the delay</td>\n</tr>\n<tr class=\"even\">\n<td>relationship <strong>with/between</strong></td>\n<td>relationship with colleagues; relationship between two groups</td>\n</tr>\n<tr class=\"odd\">\n<td>solution <strong>to</strong></td>\n<td>a solution to the problem</td>\n</tr>\n<tr class=\"even\">\n<td>response <strong>to</strong></td>\n<td>response to the complaint</td>\n</tr>\n<tr class=\"odd\">\n<td>responsibility <strong>for</strong></td>\n<td>responsibility for the project</td>\n</tr>\n<tr class=\"even\">\n<td>similarity <strong>between</strong></td>\n<td>similarity between the two plans</td>\n</tr>\n<tr class=\"odd\">\n<td>advantage <strong>of</strong></td>\n<td>the advantage of online learning</td>\n</tr>\n<tr class=\"even\">\n<td>difficulty <strong>in/with</strong></td>\n<td>difficulty in understanding; difficulty with the software</td>\n</tr>\n<tr class=\"odd\">\n<td>contribution <strong>to</strong></td>\n<td>contribution to society</td>\n</tr>\n<tr class=\"even\">\n<td>influence <strong>on/over</strong></td>\n<td>influence on public opinion</td>\n</tr>\n</tbody>\n</table></div>\n<blockquote>\n<p><em>The reason <strong>for</strong> the delay is unclear.</em><br />\n<em>We need a solution <strong>to</strong> this problem.</em><br />\n<em>The new policy had an effect <strong>on</strong> the staff.</em></p>\n</blockquote>\n<hr />\n","<h2 id=\"১০-fixed-phrase-ও-prepositional-expression\">১০. Fixed Phrase ও Prepositional Expression</h2>\n<p>কিছু phrase নির্দিষ্ট preposition-সহ ব্যবহৃত হয়। অর্থ ধরে preposition বদলালে phrase ভুল হতে পারে।</p>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>Phrase</th>\n<th>অর্থ</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>at first</td>\n<td>প্রথমে</td>\n</tr>\n<tr class=\"even\">\n<td>at once</td>\n<td>সঙ্গে সঙ্গে</td>\n</tr>\n<tr class=\"odd\">\n<td>at least</td>\n<td>অন্তত</td>\n</tr>\n<tr class=\"even\">\n<td>at risk</td>\n<td>ঝুঁকিতে</td>\n</tr>\n<tr class=\"odd\">\n<td>by chance</td>\n<td>ঘটনাক্রমে</td>\n</tr>\n<tr class=\"even\">\n<td>by mistake</td>\n<td>ভুলবশত</td>\n</tr>\n<tr class=\"odd\">\n<td>by hand</td>\n<td>হাতে</td>\n</tr>\n<tr class=\"even\">\n<td>on purpose</td>\n<td>ইচ্ছাকৃতভাবে</td>\n</tr>\n<tr class=\"odd\">\n<td>on time</td>\n<td>নির্ধারিত সময়ে</td>\n</tr>\n<tr class=\"even\">\n<td>in time</td>\n<td>দেরি হওয়ার আগেই/যথাসময়ে</td>\n</tr>\n<tr class=\"odd\">\n<td>in advance</td>\n<td>আগেভাগে</td>\n</tr>\n<tr class=\"even\">\n<td>in danger</td>\n<td>বিপদে</td>\n</tr>\n<tr class=\"odd\">\n<td>in charge of</td>\n<td>দায়িত্বে</td>\n</tr>\n<tr class=\"even\">\n<td>in fact</td>\n<td>প্রকৃতপক্ষে</td>\n</tr>\n<tr class=\"odd\">\n<td>in favour of</td>\n<td>পক্ষে</td>\n</tr>\n<tr class=\"even\">\n<td>in addition to</td>\n<td>ছাড়াও</td>\n</tr>\n<tr class=\"odd\">\n<td>under pressure</td>\n<td>চাপের মধ্যে</td>\n</tr>\n<tr class=\"even\">\n<td>under control</td>\n<td>নিয়ন্ত্রণে</td>\n</tr>\n<tr class=\"odd\">\n<td>out of order</td>\n<td>অচল/বিকল</td>\n</tr>\n<tr class=\"even\">\n<td>according to</td>\n<td>অনুযায়ী</td>\n</tr>\n<tr class=\"odd\">\n<td>because of</td>\n<td>কারণে</td>\n</tr>\n<tr class=\"even\">\n<td>due to</td>\n<td>কারণে</td>\n</tr>\n<tr class=\"odd\">\n<td>in spite of</td>\n<td>সত্ত্বেও</td>\n</tr>\n<tr class=\"even\">\n<td>with regard to</td>\n<td>সম্পর্কে/বিষয়ে</td>\n</tr>\n<tr class=\"odd\">\n<td>in accordance with</td>\n<td>অনুসারে</td>\n</tr>\n<tr class=\"even\">\n<td>on behalf of</td>\n<td>পক্ষে</td>\n</tr>\n<tr class=\"odd\">\n<td>in terms of</td>\n<td>দিক থেকে/পরিভাষায়</td>\n</tr>\n</tbody>\n</table></div>\n<h3 id=\"on-time-বনাম-in-time\">On time বনাম In time</h3>\n<ul>\n<li><strong>on time</strong> = নির্ধারিত সময়েই\n<ul>\n<li><em>The interview started <strong>on time</strong>.</em></li>\n</ul></li>\n<li><strong>in time</strong> = দেরি বা সমস্যা হওয়ার আগেই\n<ul>\n<li><em>We arrived <strong>in time</strong> to catch the bus.</em></li>\n</ul></li>\n</ul>\n<hr />\n","<h2 id=\"১১-preposition-এর-পরে-gerund\">১১. Preposition-এর পরে Gerund</h2>\n<p>Preposition-এর পরে verb এলে সাধারণত <strong>V-ing</strong> form বসে। এই V-ing তখন gerund হিসেবে কাজ করে।</p>\n<ul>\n<li>✅ <em>She is interested <strong>in learning</strong> English.</em></li>\n<li>✅ <em>He left without <strong>saying</strong> goodbye.</em></li>\n<li>✅ <em>They succeeded by <strong>working</strong> together.</em></li>\n<li>❌ <em>interested in learn</em></li>\n<li>❌ <em>without say</em></li>\n</ul>\n<h3 id=\"to-সবসময়-infinitive-marker-নয়\">“To” সবসময় infinitive marker নয়</h3>\n<p>কিছু phrase-এ <strong>to</strong> preposition, তাই এর পরে gerund হয়:</p>\n<ul>\n<li>look forward <strong>to meeting</strong> you</li>\n<li>object <strong>to changing</strong> the rule</li>\n<li>be accustomed <strong>to working</strong> at night</li>\n<li>be committed <strong>to improving</strong> services</li>\n<li>prefer walking <strong>to driving</strong></li>\n</ul>\n<p>তুলনা:</p>\n<ul>\n<li><strong>want to go</strong> — এখানে <em>to</em> infinitive marker; এর পরে V1।</li>\n<li><strong>look forward to going</strong> — এখানে <em>to</em> preposition; এর পরে gerund।</li>\n</ul>\n<h3 id=\"verb--preposition--gerund\">Verb + preposition + gerund</h3>\n<ul>\n<li>insist <strong>on paying</strong></li>\n<li>succeed <strong>in solving</strong></li>\n<li>apologize <strong>for arriving</strong> late</li>\n<li>prevent them <strong>from entering</strong></li>\n<li>think <strong>about applying</strong></li>\n<li>devote time <strong>to preparing</strong></li>\n</ul>\n<hr />\n","<h2 id=\"১২-কারণ-বৈপরীত্য-ও-শর্ত-বোঝানো-expression\">১২. কারণ, বৈপরীত্য ও শর্ত বোঝানো Expression</h2>\n<h3 id=\"because-বনাম-because-of\">Because বনাম Because of</h3>\n<ul>\n<li><strong>because + clause</strong>\n<ul>\n<li><em>The match was cancelled <strong>because it was raining</strong>.</em></li>\n</ul></li>\n<li><strong>because of + noun/noun phrase</strong>\n<ul>\n<li><em>The match was cancelled <strong>because of the rain</strong>.</em></li>\n</ul></li>\n</ul>\n<h3 id=\"although-বনাম-despitein-spite-of\">Although বনাম Despite/In spite of</h3>\n<ul>\n<li><p><strong>although/though + clause</strong></p>\n<ul>\n<li><em>Although it was raining, the match continued.</em></li>\n</ul></li>\n<li><p><strong>despite/in spite of + noun বা gerund</strong></p>\n<ul>\n<li><em>Despite the rain, the match continued.</em></li>\n<li><em>In spite of being tired, she continued working.</em></li>\n</ul></li>\n<li><p>❌ <em>Despite it was raining…</em></p></li>\n<li><p>✅ <em>Although it was raining…</em></p></li>\n<li><p>✅ <em>Despite the rain…</em></p></li>\n</ul>\n<h3 id=\"during-বনাম-while\">During বনাম While</h3>\n<ul>\n<li><strong>during + noun:</strong> <em>during the class</em></li>\n<li><strong>while + subject + verb:</strong> <em>while the class was going on</em></li>\n</ul>\n<h3 id=\"in-case-of-বনাম-in-case\">In case of বনাম In case</h3>\n<ul>\n<li><strong>in case of + noun:</strong> <em>In case of fire, use the stairs.</em></li>\n<li><strong>in case + clause:</strong> <em>Take an umbrella in case it rains.</em></li>\n</ul>\n<hr />\n","<h2 id=\"১৩-চাকরির-পরীক্ষায়-সাধারণ-ভুল-ও-ফাঁদ\">১৩. চাকরির পরীক্ষায় সাধারণ ভুল ও ফাঁদ</h2>\n<div class=\"table-wrap\"><table class=\"study-table\">\n<thead>\n<tr class=\"header\">\n<th>ভুল pattern</th>\n<th>সঠিক pattern</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>discuss about the issue</td>\n<td>discuss the issue</td>\n</tr>\n<tr class=\"even\">\n<td>enter into the room</td>\n<td>enter the room</td>\n</tr>\n<tr class=\"odd\">\n<td>reach to the station</td>\n<td>reach the station</td>\n</tr>\n<tr class=\"even\">\n<td>arrive to Dhaka</td>\n<td>arrive in Dhaka</td>\n</tr>\n<tr class=\"odd\">\n<td>arrive to the station</td>\n<td>arrive at the station</td>\n</tr>\n<tr class=\"even\">\n<td>married with someone</td>\n<td>married to someone</td>\n</tr>\n<tr class=\"odd\">\n<td>prefer tea than coffee</td>\n<td>prefer tea to coffee</td>\n</tr>\n<tr class=\"even\">\n<td>superior than the other model</td>\n<td>superior to the other model</td>\n</tr>\n<tr class=\"odd\">\n<td>different than the original (পরীক্ষার প্রচলিত উত্তর)</td>\n<td>different from the original</td>\n</tr>\n<tr class=\"even\">\n<td>between you and I</td>\n<td>between you and me</td>\n</tr>\n<tr class=\"odd\">\n<td>despite it was raining</td>\n<td>although it was raining / despite the rain</td>\n</tr>\n<tr class=\"even\">\n<td>because of he was ill</td>\n<td>because he was ill / because of his illness</td>\n</tr>\n<tr class=\"odd\">\n<td>since five years</td>\n<td>for five years</td>\n</tr>\n<tr class=\"even\">\n<td>for 2020</td>\n<td>since 2020</td>\n</tr>\n<tr class=\"odd\">\n<td>during I was studying</td>\n<td>while I was studying</td>\n</tr>\n<tr class=\"even\">\n<td>look forward to meet</td>\n<td>look forward to meeting</td>\n</tr>\n<tr class=\"odd\">\n<td>interested to learning</td>\n<td>interested in learning</td>\n</tr>\n<tr class=\"even\">\n<td>good in mathematics</td>\n<td>good at mathematics</td>\n</tr>\n<tr class=\"odd\">\n<td>depend of the result</td>\n<td>depend on the result</td>\n</tr>\n<tr class=\"even\">\n<td>accused for theft</td>\n<td>accused of theft</td>\n</tr>\n<tr class=\"odd\">\n<td>solution of the problem</td>\n<td>solution to the problem</td>\n</tr>\n<tr class=\"even\">\n<td>reason of the delay</td>\n<td>reason for the delay</td>\n</tr>\n<tr class=\"odd\">\n<td>on the bus stop</td>\n<td>at the bus stop</td>\n</tr>\n</tbody>\n</table></div>\n<hr />\n","<h2 id=\"১৪-mcq-সমাধানের-কার্যকর-পদ্ধতি\">১৪. MCQ সমাধানের কার্যকর পদ্ধতি</h2>\n<p>Preposition-সংক্রান্ত প্রশ্নে blank দেখলে এই ধাপে বিচার করুন:</p>\n<ol type=\"1\">\n<li><strong>সম্পর্কটি শনাক্ত করুন:</strong> সময়, স্থান, দিক, কারণ, মাধ্যম, নাকি শব্দের fixed collocation?</li>\n<li><strong>Blank-এর আগে-পরে থাকা শব্দ দেখুন:</strong> এটি verb, adjective না noun-এর সঙ্গে যুক্ত?</li>\n<li><strong>পুরো phrase মনে করুন:</strong> যেমন <em>depend on</em>, <em>interested in</em>, <em>reason for</em>।</li>\n<li><strong>Noun/gerund/clause আছে কি যাচাই করুন:</strong>\n<ul>\n<li>despite + noun/gerund</li>\n<li>although + clause</li>\n<li>during + noun</li>\n<li>while + clause</li>\n</ul></li>\n<li><strong>Preposition ছাড়াই ব্যবহৃত verb মনে রাখুন:</strong> <em>discuss, enter, reach, approach, mention, resemble</em>।</li>\n<li><strong>সব option বসিয়ে বাক্যটি পড়ুন:</strong> অর্থ ও grammar—দুটিই ঠিক হচ্ছে কি না দেখুন।</li>\n<li><strong>শুধু বাংলা থেকে অনুবাদ করে preposition বাছবেন না:</strong> ইংরেজি collocation মুখস্থ ও অনুশীলন করুন।</li>\n</ol>\n<h3 id=\"দ্রুত-স্মরণসূত্র\">দ্রুত স্মরণসূত্র</h3>\n<ul>\n<li><strong>at</strong> a time; <strong>on</strong> a day/date; <strong>in</strong> a month/year/period</li>\n<li><strong>since</strong> + starting point; <strong>for</strong> + duration</li>\n<li><strong>by</strong> = deadline-এর মধ্যে; <strong>until</strong> = সময় পর্যন্ত চলা</li>\n<li><strong>during</strong> + noun; <strong>while</strong> + clause</li>\n<li><strong>between</strong> = পৃথক পক্ষের মধ্যে; <strong>among</strong> = দলের মধ্যে</li>\n<li><strong>into/onto</strong> = চলাচল; <strong>in/on</strong> = অবস্থান</li>\n<li><strong>because of/despite</strong> + noun phrase; <strong>because/although</strong> + clause</li>\n<li><strong>Preposition-এর পরে verb হলে সাধারণত V-ing</strong></li>\n<li><strong>Verb + preposition, adjective + preposition, noun + preposition</strong>—একসঙ্গে phrase হিসেবে শিখুন।</li>\n</ul>\n"];
