function chapterNote(topic,ci,title,qs){if(topic.id==="tense")return tenseFullNote[ci];
 const guide=chapterGuides[topic.id][ci],support=noteText[topic.id][ci%noteText[topic.id].length];
 const q=qs[0],opts=q[1].map((o,i)=>String.fromCharCode(65+i)+". "+o).join(" | ");
 const rows=[
  ["Core rule / pattern",guide],
  ["Common confusion",confusion[topic.id][ci%confusion[topic.id].length]],
  ["IBA · Bank · BCS trap",examTrap[topic.id][ci%examTrap[topic.id].length]],
  ["How to solve",examApproach[topic.id]]
 ].map(r=>`<tr><th>${htmlSafe(r[0])}</th><td>${htmlSafe(r[1])}</td></tr>`).join("");
 return `<h3>1. Core concept and rule</h3><p>${htmlSafe(guide)}</p>
 ${topic.id==="tense"?tenseExtras[ci]:""}
 <h3>2. Exam-focused comparison</h3><div class="table-wrap"><table class="study-table"><tbody>${rows}</tbody></table></div>
 <h3>3. Pattern to remember</h3><p>${htmlSafe(support)}</p>
 <h3>4. Worked exam-style example</h3><div class="example-box"><p><b>${htmlSafe(q[0])}</b></p><p>${htmlSafe(opts)}</p><p class="answer-note"><b>Answer: ${String.fromCharCode(65+q[2])}. ${htmlSafe(q[1][q[2]])}</b> — ${htmlSafe(q[3])}</p></div>
 <h3>5. Last-minute checklist</h3><ul><li>Read the whole sentence and locate the exact rule being tested.</li><li>Check meaning, word class, time/number agreement and collocation before comparing options.</li><li>Eliminate rule-breaking choices, then reread with your answer inserted.</li></ul>
 <div class="important"><b>Chapter focus:</b> ${htmlSafe(title)}. IBA-style distractors may be grammatically possible but wrong in meaning, form or collocation.</div>`;
}
topics.forEach((t,ti)=>{t.chapters=t.chapters.map((title,ci)=>({title:(ci+1)+". "+title,lead:chapterGuides[t.id][ci],notes:chapterNote(t,ci,title,genericQuestions(t,ci)),qs:genericQuestions(t,ci)}))});
const tenseTopic=topics.find(t=>t.id==="tense");tenseTopic.chapters=tenseFullNote.map((notes,i)=>({title:(i+1)+". "+["Tense-এর ধারণা, ১২টি গঠন ও ব্যবহার","Tense বাছাই ও সময়-সম্পর্ক","Clause: ধরন, গঠন ও ব্যবহার","Future time clause ও connectors","Conditional clause: Zero থেকে Third","Inversion: negative ও restrictive expressions","Subject–Verb Agreement: নিয়ম ও ব্যতিক্রম","Reported Speech / Narration","Competitive exam traps: Grammar mixed practice","Revision strategy ও final mixed drill"][i],lead:["কাল, verb form, affirmative/negative/question গঠন এবং ১২টি tense-এর মূল ব্যবহার।","সময়চিহ্ন, since/for, finished time, sequence of events এবং tense নির্বাচন।","Independent/dependent, noun, relative, adverb, finite ও non-finite clause।","When, before, after, until, as soon as, once ও by the time-এর ব্যবহার।","বাস্তব ও কাল্পনিক শর্ত, unless, provided that এবং তিন ধরনের conditional pattern।","Never, hardly, no sooner, not until, only, conditional inversion, so/neither।","Head noun, each/every, proximity, collective/uncountable noun, amount ও relative clause।","Backshift, pronoun/time word, question, command, request, advice, exclamation ও wish।","Tense, clause, time clause, inversion, agreement ও narration-এর সাধারণ ভুল অপশন।","পরীক্ষায় দ্রুত rule শনাক্ত করা, option elimination এবং পূর্ণাঙ্গ revision framework।"][i],notes:notes,qs:tenseQuestionBank[i].map(q=>[q[0],q[1].split("|"),q[2],q[3]])}));
